import json, random, subprocess, sys, copy
sys.path.insert(0, '/app/tmp')
import ref
import importlib.util
sp = importlib.util.spec_from_file_location('mm', '/app/submit/main.py')
mm = importlib.util.module_from_spec(sp); sp.loader.exec_module(mm)
from fractions import Fraction

def run(lines):
    p = subprocess.run(['/app/submit/run'], input='\n'.join(lines)+'\n', text=True,
                       capture_output=True, timeout=600)
    assert p.returncode == 0, p.stderr
    return [json.loads(x) for x in p.stdout.splitlines()]

def rand_fib(rng, n):
    fib=[]; seen=set()
    while len(fib)<n:
        L=rng.choice([0,1,2,4,8,16,24,32,48,64,80,96,112,120,127,128])
        net=(rng.getrandbits(L)<<(128-L)) if L else 0
        if (net,L) in seen: continue
        seen.add((net,L)); fib.append((net,L,rng.randrange(65536)))
    return fib

def build_image(fib, caps, ms, cuts):
    stages, used = ref.spec_nodes(fib, cuts)
    pk = max(Fraction(u, c) for u, c in zip(used, caps))
    return {'status':'ok','capacities':caps,'max_stride':ms,'cuts':cuts,
            'stages':stages,'used_bits':used,'peak':{'num':pk.numerator,'den':pk.denominator}}

def rules_of(img):
    out=[]
    for st in img['stages']:
        for nd in st['nodes']:
            for r in nd['rules']:
                pr = mm.parse_prefix(r['prefix'])
                if pr: out.append((pr[0], pr[1], r['hop']))
    return out

def mutate(rng, img):
    im = copy.deepcopy(img)
    k = rng.randrange(14)
    try:
        if k == 0: im['used_bits'][rng.randrange(len(im['used_bits']))] += 64
        elif k == 1: im['peak']['num'] += 1
        elif k == 2: im['cuts'][rng.randrange(1, len(im['cuts']))] += 1
        elif k == 3:
            for nd in im['stages'][-1]['nodes']:
                if nd['rules']: nd['rules'].pop(0); break
        elif k == 4:
            for nd in im['stages'][0]['nodes']:
                if nd['rules']: nd['rules'][0]['hop'] ^= 1; break
        elif k == 5:
            for nd in im['stages'][1]['nodes']:
                if nd['edges']: nd['edges'][0]['child'] ^= 1; break
        elif k == 6: im['stages'][0]['nodes'][0]['prefix'] = '0:0:0:0:0:0:0:0/0'
        elif k == 7: im['stages'].append(im['stages'][-1])
        elif k == 8: im['stages'][0]['nodes'][0]['edges'] = im['stages'][0]['nodes'][0]['edges'] + im['stages'][0]['nodes'][0]['edges']
        elif k == 9: im['max_stride'] = 1
        elif k == 10: im['stages'][0]['nodes'] = []
        elif k == 11: im['capacities'][0] = 1
        elif k == 12:
            for nd in im['stages'][0]['nodes']:
                if nd['rules']: nd['rules'].insert(0, nd['rules'][-1]); break
        else: return im, False
    except Exception:
        return im, True
    return im, True

def main():
    seed = int(sys.argv[1]); rng = random.Random(seed)
    lines=[]; metas=[]
    for t in range(40):
        n = rng.choice([0,1,2,3,8,25,60])
        fib = rand_fib(rng, n)
        S = rng.choice([4,5,6,7,8,16]); ms = 32
        caps=[rng.choice([10**7, 10**8, 10**9]) for _ in range(S)]
        img = build_image(fib, caps, ms, [i*128//(S) for i in range(S+1)] if 128 % S == 0 else None)
        if img is None: continue
        addrs=[]
        for _ in range(50):
            if fib and rng.random()<0.6:
                net,L,h = fib[rng.randrange(len(fib))]
                addrs.append(ref.fmt(net + (rng.getrandbits(128-L) if L<128 else 0)))
            else:
                addrs.append(ref.fmt(rng.getrandbits(128)))
        do_mut = rng.random() < 0.4
        img2, mut = mutate(rng, img) if do_mut else (img, False)
        lines.append(json.dumps({'op':'lookup','image':img2,'addresses':addrs}))
        metas.append((fib, addrs, img2, mut))
    resps = run(lines)
    nacc = 0
    for i,(fib, addrs, img2, mut) in enumerate(metas):
        r = resps[i]
        if r.get('status') != 'ok':
            continue
        nacc += 1
        rr = rules_of(img2)
        for a, ans in zip(addrs, r['answers']):
            v = mm.parse_addr(a)
            h, L = ref.lpm(rr, v)
            exp = {'hop':h,'prefix_length':L} if L >= 0 else {'hop':None,'prefix_length':None}
            assert ans == exp, (i, a, ans, exp)
    print('lookup2 OK seed', seed, 'accepted', nacc, 'of', len(metas))

main()
